  function _tempoEintraege() {
    const pid = _tempoProjektId();
    if (Array.isArray(_tempoListe) && _tempoListeVon === pid) return _tempoListe;
    const p = (typeof getActiveProject === "function") ? getActiveProject() : null;
    let e = p?.[_MODKEY]?.tempo_eintraege;
    if (!Array.isArray(e)) {
      try { e = (_settingsCache && _settingsCache[_MODKEY] || {}).tempo_eintraege; } catch (_) { e = null; }
    }
    _tempoListe = Array.isArray(e) ? e.slice() : [];
    _tempoListeVon = pid;
    return _tempoListe;
  }
  function _tempoEintraegeSetzen(liste) {
    try { if (!window.__rzUndoApplying) _animPushUndo(t("undo.tempo_geaendert", "Tempo-Spur geändert")); } catch (_) {}   // 10.09.2026
    _tempoListe = Array.isArray(liste) ? liste.slice() : [];
    _tempoListeVon = _tempoProjektId();
    try { saveProjectSettings(_MODKEY, { tempo_eintraege: _tempoListe }); } catch (_) {}
  }
  // Prüfstand-Griff: Einträge setzen und die Kurve neu holen, ohne die Spur mit
  // der Maus bedienen zu müssen (tests/test_tempo_spur_zeitband.py).
  window.__rzTempoSetzen = (liste) => { _tempoEintraegeSetzen(liste); paceMapLaden(); };
  window.__rzTempoInfo = () => _tempoInfo;
  function _tempoRate() {
    const p = (typeof getActiveProject === "function") ? getActiveProject() : null;
    const r = p?.[_MODKEY]?.tempo_rate;
    return (typeof r === "number" && isFinite(r) && r > 0) ? r : null;
  }
  /** Unter welcher Grundlage die gespeicherte Raffung entstand — "" bei alten
   *  Projekten (die kannten nur die Strecke). */
  function _tempoBasisGespeichert() {
    const p = (typeof getActiveProject === "function") ? getActiveProject() : null;
    const b = p?.[_MODKEY]?.tempo_basis;
    return (typeof b === "string") ? b : "";
  }
  function _tempoRateSichern(rate, basis) {
    try { saveProjectSettings(_MODKEY, { tempo_rate: rate, tempo_basis: basis }); } catch (_) {}
  }

  /** Die Dauer ist ab jetzt ein ERGEBNIS: Raffung plus Halte plus gebremste
   *  Abschnitte. Sie wird in das Dauer-Feld geschrieben, damit alles dahinter
   *  (Zeitleiste, Keyframe-Zeiten, Render-Auftrag) unverändert damit rechnet. */
  function _tempoDauerAnzeigen(r, nurAnzeigen) {
    if (!r || !isFinite(r.dauer_s) || r.dauer_s <= 0) return;
    const feld = document.getElementById("anim-dur");
    const neu = Math.max(1, Math.round(r.dauer_s * 10) / 10);
    // Bei einer Reise ist die Dauer die Vorgabe, nicht das Ergebnis — sie darf
    // hier nicht überschrieben werden.
    if (!nurAnzeigen && feld && Math.abs(parseNum(feld.value, 0) - neu) > 0.05) {
      _tempoSchreibt = true;
      feld.value = neu;
      try { feld.dispatchEvent(new Event("change", { bubbles: true })); } finally { _tempoSchreibt = false; }
    }
    const raff = r.basis === "zeit" ? `${Math.round(r.rate)}×`
      : r.basis === "strecke" ? `${(r.rate).toFixed(2)} km/s`
      : `${Math.round(r.rate)} Pkt/s`;
    const satz = t("animator.tempo.bilanz", "{raff} · {ges} s — Strecke {str} s, Halte {halt} s")
      .replace("{raff}", raff).replace("{ges}", r.dauer_s.toFixed(1))
      .replace("{str}", r.sek_strecke.toFixed(1)).replace("{halt}", r.sek_halte.toFixed(1));
    // Zwei Plätze: in der Seitenleiste beim Verteilungs-Feld und — weil der
    // Abschnitt dort meist zugeklappt ist — dauerhaft unter der Tempo-Spur.
    // Bei einer Reise steht unter der Spur die Reise-Bilanz — sie sagt, was
    // Etappen und Übergänge kosten. Die Raffung gehört dann in die Seitenleiste.
    for (const id of nurAnzeigen ? ["anim-tempo-bilanz"] : ["anim-tempo-bilanz", "tl-tempo-bilanz"]) {
      const z = document.getElementById(id);
      if (!z) continue;
      z.hidden = false;
      z.textContent = satz;
      z.dataset.quelle = "tempo";   // 25.09.2026 — s. _reiseBilanzZeigen
      z.classList.toggle("warnt", r.sek_halte > r.sek_strecke);
    }
  }

  /** Kleiner Editor für einen Tempo-Eintrag (Doppelklick in der Spur). */
  function _tempoEintragOeffnen(i, e) {
    const liste = _tempoEintraege().slice();
    const eintrag = liste[i];
    if (!eintrag) return;
    const istHalt = eintrag.art === "halt";
    const m = openModal({
      title: istHalt ? t("animator.tempo.halt_titel", "Halt")
                     : t("animator.tempo.abschnitt_titel", "Abschnitt"),
      body: `<div class="lib-fmodal">
        ${istHalt ? `
          <label class="field-label" for="tempo-sek">${t("animator.tempo.sekunden", "Sekunden stehen")}</label>
          <input type="number" id="tempo-sek" class="lib-input" min="0.1" step="0.5" value="${(+eintrag.sek || 2).toFixed(1)}">
          <label class="field-label" for="tempo-kam" style="margin-top:10px;">${t("animator.tempo.kamera", "Kamera dabei")}</label>
          <select id="tempo-kam" class="lib-select">
            <option value="nichts"${eintrag.kamera !== "orbit" ? " selected" : ""}>${t("animator.tempo.kam_nichts", "steht still — deine Keyframes gelten")}</option>
            <option value="orbit"${eintrag.kamera === "orbit" ? " selected" : ""}>${t("animator.tempo.kam_orbit", "dreht sich langsam um die Stelle")}</option>
          </select>` : `
          <label class="field-label" for="tempo-faktor">${t("animator.tempo.faktor", "Tempo in diesem Abschnitt")}</label>
          <select id="tempo-faktor" class="lib-select">
            ${[0.1, 0.25, 0.5, 0.75, 1, 1.5, 2, 4].map(f =>
              `<option value="${f}"${Math.abs((+eintrag.faktor || 1) - f) < 1e-6 ? " selected" : ""}>${f}× ${
                f < 1 ? t("animator.tempo.langsamer", "langsamer") : (f > 1 ? t("animator.tempo.schneller", "schneller") : t("animator.tempo.normal", "normal"))}</option>`).join("")}
          </select>`}
        <div class="lib-hint" style="margin-top:10px;">${
          istHalt ? t("animator.tempo.halt_hinweis", "Ein Halt verlängert das Video um seine Sekunden.")
                  : t("animator.tempo.abschnitt_hinweis", "Der Faktor zählt gegen die Grundraffung. Langsamer heißt: dieser Abschnitt braucht mehr Videozeit.")}</div>
        <div class="lib-actions" style="margin-top:12px;">
          <button class="btn btn-primary btn-sm" id="tempo-ok">${t("common.ok", "Übernehmen")}</button>
          <button class="btn btn-ghost btn-sm lib-btn-danger" id="tempo-weg">${t("animator.tempo.entfernen", "Entfernen")}</button>
        </div>
      </div>`,
    });
    const fertig = (neueListe) => {
      _tempoEintraegeSetzen(neueListe);
      try {
        if (_tlBar && _tlBar.setTempo)
          _tlBar.setTempo(neueListe, (_tempoInfo && _tempoInfo.halte) || [],
                          _tempoInfo ? { dauer_s: _tempoInfo.dauer_s, anteile: _tempoInfo.map } : null);
      } catch (_) {}
      // Ein Fehlschlag darf die Eingabe nicht abbrechen — die Tabelle bleibt dann
      // die vorherige, und der nächste Anlauf holt sie nach.
      // ui-falle-ok: Kurve wird bei jeder weiteren Änderung erneut geholt
      try { paceMapLaden(); } catch (_) {}
      m.close();
    };
    const ok = document.getElementById("tempo-ok");
    if (ok) ok.onclick = () => {
      if (istHalt) {
        eintrag.sek = Math.max(0.1, parseFloat(document.getElementById("tempo-sek").value) || 2);
        eintrag.kamera = document.getElementById("tempo-kam").value || "nichts";
      } else {
        eintrag.faktor = Math.max(0.01, parseFloat(document.getElementById("tempo-faktor").value) || 1);
      }
      fertig(liste);
    };
    const weg = document.getElementById("tempo-weg");
    if (weg) weg.onclick = () => { liste.splice(i, 1); fertig(liste); };
  }

  /** Die Tempo-Spur mit der zuletzt geholten Kurve (neu) füllen.
   *  25.09.2026 (Klicktest AN-03: Intro 2 / Animation 10 / Hold 2 → Spur zeigte
   *  „Nachlauf 5,0 s") — Anlauf und Nachlauf sind gesperrte Halte, deren Länge
   *  `_tempoAnzeige` aus den Feldern liest. An die Spur gingen sie aber nur, wenn
   *  die Kurve neu geholt wurde, und das tat nur das Dauer-Feld. Intro und Hold
   *  änderten die Geometrie (`setTrackFraction`), die Beschriftung blieb beim
   *  alten Wert — und ein Hold, der beim Laden 0 war, erschien gar nicht. Die
   *  Kurve selbst hängt nicht an Intro/Hold, darum genügt hier das Neuzeichnen
   *  mit dem gemerkten Stand (keine Brücke). */
  let _tempoSpurStand = null;   // { reise, halte, kurve } aus dem letzten paceMapLaden
  function _tempoSpurZeigen(eintraege) {
    const st = _tempoSpurStand;
    if (!st || !_tlBar || !_tlBar.setTempo) return;
    try {
      const reise = st.reise;
      const kurve = reise ? { dauer_s: animSekunden(), anteile: null } : st.kurve;
      _tlBar.setTempo(_tempoAnzeige(reise ? [] : (eintraege || _tempoEintraege())), st.halte, kurve,
                      reise ? t("animator.tempo.gruppen_hinweis",
                                "Der Zeitplan kommt aus den Gruppen: Kachel ziehen verschiebt sie in der Zeit, die Ränder ändern ihre Länge, Doppelklick öffnet sie.")
                            : null);
    } catch (_) {}
  }

  async function paceMapLaden() {
    const lauf = ++_paceMapLauf;
    if (!currentGpx) { _paceMap = null; _tempoInfo = null; vorschauNeuZeichnen(); return; }
    const basis = _tempoBasis();
    const eintraege = _tempoEintraege();
    // ── Eine Reise bringt ihren eigenen Zeitplan mit ────────────────────────
    // Die Etappen und die Übergänge teilen die Animationszeit auf; die Bahn ist
    // dadurch schon gleichmäßig in Videozeit abgetastet. Eine zweite Verteilung
    // darüber wäre eine zweite Wahrheit. Deshalb gilt hier: die Dauer aus der
    // Seitenleiste führt, die Raffung wird über ALLE Etappen daraus abgeleitet
    // und nur angezeigt — die Kurve verteilt nichts (08.09.2026).
    const reise = _reiseGilt();
    // Ohne Einträge und ohne gespeicherte Raffung: die Dauer aus der Seitenleiste
    // führt, die Raffung wird daraus abgeleitet. Genau so laufen alle bestehenden
    // Projekte weiter (Marc: „das muss abwärtskompatibel bleiben").
    // 09.09.2026 (Marc: „den Probe-Lauf kann ich nicht mehr starten, das hängt"):
    // Die Raffung war als 2,95 km je Videosekunde gespeichert (Grundlage
    // „Strecke"), der Tempo-Modus des Projekts stand aber auf „Punkte" — die
    // Zahl wurde als 2,95 Punkte je Sekunde gelesen, das Video 10 216 s lang,
    // der Probe-Lauf lief unsichtbar langsam. Eine Raffung gilt nur unter der
    // Grundlage, unter der sie entstand. Passt die nicht mehr, führt die Dauer
    // aus der Seitenleiste und die Raffung wird neu abgeleitet und gesichert.
    const rateGespeichert = reise ? 0 : _tempoRate();
    const basisGespeichert = _tempoBasisGespeichert();
    const rate = (rateGespeichert && basisGespeichert && basisGespeichert !== basis) ? 0 : rateGespeichert;
    if (rateGespeichert && !rate) {
      applog("info", `[tempo] Raffung ${rateGespeichert.toFixed(3)} galt für „${basisGespeichert}“, jetzt gilt „${basis}“ — wird aus der Dauer (${parseNum(document.getElementById("anim-dur")?.value, 12)} s) neu abgeleitet`);
    }
    try {
      const r = await api().animator_tempo_map({
        gpx_path: currentGpx,
        // Bei einer Reise gilt die Raffung für ALLE Etappen zusammen — sonst
        // rechnet die Kurve nur mit der ersten und schreibt deren Dauer in das
        // Feld, das den ganzen Reiseplan bestimmt (08.09.2026).
        gpx_paths: reise
          ? (_reiseBahn ? _reiseBahn.etappen.map(e => e.tour.gpx_path)
                        : [currentGpx].concat(_extraTours.map(x => x.gpx_path).filter(Boolean)))
          : null,
        basis,
        rate: rate || 0,
        dauer_s: parseNum(document.getElementById("anim-dur")?.value, 12),
        eintraege: reise ? [] : eintraege.concat(_lbTempo(), _fotostoppHalte()),   // 24.09.2026 — + Logbuch raffen/überspringen; 01.10.2026 + Fotostopps
        fps: parseNum(document.getElementById("anim-fps")?.value, 30),
        pause_mode: document.getElementById("anim-pause-mode")?.value || "trim",
        pause_min_s: (parseFloat(document.getElementById("anim-pause-min")?.value) || 2) * 60,
        pause_trim_s: (function () {
          const v = parseFloat(document.getElementById("anim-pause-trim")?.value);
          return isNaN(v) ? 5 : v;
        })(),
      });
      if (lauf !== _paceMapLauf) return;             // veraltete Antwort
      if (r && r.ok && Array.isArray(r.map)) {
        _fsKurveStand = JSON.stringify(_fotostoppHalte());
        _paceMap = reise ? null : r.map;
        _tempoInfo = r;
        if (!reise && !rate && r.rate) _tempoRateSichern(r.rate, basis);   // einmalig ableiten
        _tempoDauerAnzeigen(r, reise);
        _tempoSpurStand = { reise, halte: reise ? [] : (r.halte || []),
                            // Bei einer Etappenfolge OHNE Tabelle (die Bahn ist
                            // schon gleichmäßig in Videozeit), aber MIT der
                            // Länge — die Kacheln beschriften sich daraus.
                            kurve: reise ? { dauer_s: animSekunden(), anteile: null }
                                         : { dauer_s: r.dauer_s, anteile: r.map } };
        _tempoSpurZeigen(eintraege);
        // §60 Punkt 6 — jetzt, mit neuer Kurve UND neuer Dauer im Feld: die
        // Keyframes an ihre Strecke nachziehen.
        try { _keyframesNachziehen(); } catch (e) { applog("warn", "[keyframes] " + e); }
        // 06.10.2026 — die Schilder-Spur kennt die Fotostopps erst mit den Halten: neu zeichnen (sonst stand der
        // Fotostopp-Balken bis zur nächsten Änderung auf dem kurzen Schild-Fenster)
        try { _sgSpurAktualisieren(); } catch (_) {}
      } else { _paceMap = null; _tempoInfo = null; }
    } catch (_) { _paceMap = null; _tempoInfo = null; }
    // Tester-Befund (ein Beta-Tester, 29.08.2026: „keine Veränderung spürbar"): auf
    // gleichmäßig gelaufenen Touren verschieben die Modi den Lauf nur um
    // wenige Prozent — das IST korrekt, sieht aber nach „wirkt nicht" aus.
    // Deshalb die messbare Wirkung DIESER Tour dazuschreiben.
    try {
      const desc = document.getElementById("anim-pace-desc");
      if (desc && _paceMap && _paceMap.length >= 2) {
        const n1 = _paceMap.length - 1;
        let maxAbw = 0;
        for (let i = 0; i <= n1; i++)
          maxAbw = Math.max(maxAbw, Math.abs(_paceMap[i] - i / n1));
        const pct = Math.round(maxAbw * 100);
        const satz = pct < 2
          ? t("animator.pace.wirkung_min", "Diese Tour wurde so gleichmäßig aufgezeichnet, dass diese Verteilung kaum sichtbar wirkt (höchstens {p} % Verschiebung).")
          : t("animator.pace.wirkung", "Wirkung bei dieser Tour: der Lauf verschiebt sich um bis zu {p} % gegenüber „gleichmäßig“.");
        desc.textContent = (desc.textContent ? desc.textContent + " " : "")
          + satz.replace("{p}", String(Math.max(1, pct)));
      }
    } catch (_) {}
    vorschauNeuZeichnen();
  }

  /** Fortschritt (0..1) → BRUCHTEIL-Index in `currentCoords` (12.4 = zwischen
   *  Punkt 12 und 13), mit der gewählten Verteilung.
   *
   *  v0.9.510 — vorher wurde hier gerundet, und ALLES rastete auf ganze
   *  Trackpunkte: der Scrubber sprang beim Loslaufen auf den nächsten Punkt
   *  (Marc hat es genau so beschrieben), und bei langer Dauer stand der Punkt
   *  mehrere Frames still und hüpfte dann weiter. */
  function fracAusFortschritt(p, n) {
    const anteil = Math.max(0, Math.min(1, p));
    let imTrack = anteil;
    if (_paceMap && _paceMap.length >= 2) {
      const x = anteil * (_paceMap.length - 1);
      const i = Math.min(_paceMap.length - 2, Math.floor(x));
      const f = x - i;
      // ⚠️ Die Tabelle enthält ANTEILE (0..1), keine Punkt-Indizes: die Vorschau
      // arbeitet mit einer reduzierten Koordinatenliste (800 statt 2951 Punkte),
      // rohe Indizes klemmten dort ab einem Viertel am Ende fest.
      imTrack = _paceMap[i] + (_paceMap[i + 1] - _paceMap[i]) * f;
    }
    return Math.max(0, Math.min(n - 1, imTrack * (n - 1)));
  }

  function idxAusFortschritt(p, n) {
    return Math.max(0, Math.min(n - 1, Math.round(fracAusFortschritt(p, n))));
  }

  /** Koordinate am Bruchteil-Index — linear zwischen den Nachbarpunkten. */
  function coordBeiFrac(coords, frac) {
    const i = Math.max(0, Math.min(coords.length - 2, Math.floor(frac)));
    const f = Math.max(0, Math.min(1, frac - i));
    const a = coords[i], b = coords[i + 1] || a;
    return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];
  }

  /** Stelle auf der Leiste → Stelle im Track.
   *
   *  ⚠️ Die Leiste ist eine TRACK-Achse (v0.9.510): wo der Scrubber steht,
   *  liegt genau diese Stelle des Tracks — dieselbe Rechnung, mit der
   *  `setTrimVisual` die gelben Griffe setzt. Vorher wurde hier auf den
   *  Bereich ZWISCHEN den Griffen gestaucht; damit lag ein Griff genau auf
   *  dem Scrubber, zeigte aber eine ganz andere Stelle des Tracks.
   *  Außerhalb der Griffe steht der Track still — wie im fertigen Video. */
  /** TRACK-Anker (0..1 über die ganze Strecke) → Stelle in `currentCoords`.
   *
   *  ⚠️ v0.9.511 — hieß früher `…FromTimelineAnchor` und bekam eine Position
   *  auf der LEISTE. Seit der Scrubber selbst in Track-Ankern spricht, ist das
   *  die einzige Größe im Umlauf — Keyframes, Schilder, Foto-Pins und
   *  Trim-Griffe rechnen alle darin. Außerhalb des Schnitts steht der Track
   *  still, genau wie im fertigen Video. */
  function trackFracAusAnker(anchor) {
    const n = currentCoords ? currentCoords.length : 0;
    if (n < 2) return 0;
    const trim = (_tlBar && typeof _tlBar.getTrim === "function")
      ? _tlBar.getTrim() : { start: 0, end: 1 };
    const trimA = Math.max(0, Math.min(1, trim.start ?? 0));
    const trimB = Math.max(trimA, Math.min(1, trim.end ?? 1));
    const markerReal = Math.max(trimA, Math.min(trimB, Math.max(0, Math.min(1, anchor))));
    return fracAusFortschritt(markerReal, n);
  }

  /** 29.08.2026 (Marc: „wir wollen immer wysiwyg") — Haupt-Start-Verzögerung
   *  auch in der Vorschau: Anteil der Animationsdauer, wortgleich zum Render
   *  (_haupt_delay_frames in core/animator.py). Nur im Schwarm aktiv. */
  function hauptStartAnteil() {
    // 09.09.2026 (§60): der eigene Vorlauf des Taktgebers IN seiner Gruppe —
    // nur ohne Bahn (eine Gruppe), in der Kette wäre die Renormierung falsch.
    if (_reiseAktiv() || !_istSchwarm()) return 0;
    const g = _gruppen[0], m = g && g.mitglieder[0];
    if (!m || _pfadNFC(m.gpx_path) !== _pfadNFC(currentGpx)) return 0;
    const sek = +m.vorlauf_s || 0;
    if (sek <= 0) return 0;
    const dur = parseInt(document.getElementById("anim-dur")?.value) || 20;
    return Math.min(0.95, Math.max(0, sek / Math.max(0.1, dur)));
  }
  /** Wie trackFracAusAnker, aber mit Haupt-Start-Verzögerung: der Haupt-Track
   *  wartet und läuft dann RENORMIERT bis zum Trim-Ende — exakt die
   *  coords_per_frame_eff-Rechnung des Renders. Trim-Griffe, Kamera-Anker und
   *  Schilder bleiben bewusst UNVERZÖGERT (auch das spiegelt den Render). */
  function trackFracAusAnkerHaupt(anchor) {
    const s = hauptStartAnteil();
    if (s <= 0) return trackFracAusAnker(anchor);
    const n = currentCoords ? currentCoords.length : 0;
    if (n < 2) return 0;
    const trim = (_tlBar && typeof _tlBar.getTrim === "function")
      ? _tlBar.getTrim() : { start: 0, end: 1 };
    const trimA = Math.max(0, Math.min(1, trim.start ?? 0));
    const trimB = Math.max(trimA, Math.min(1, trim.end ?? 1));
    const markerReal = Math.max(trimA, Math.min(trimB, Math.max(0, Math.min(1, anchor))));
    const q = (markerReal - trimA) / Math.max(1e-9, trimB - trimA);
    const qEff = Math.max(0, Math.min(1, (q - s) / (1 - s)));
    return fracAusFortschritt(trimA + qEff * (trimB - trimA), n);
  }
  function trackIdxFromTimelineAnchor(anchor) {
    const n = currentCoords ? currentCoords.length : 0;
    if (n < 2) return 0;
    return Math.max(0, Math.min(n - 1, Math.round(trackFracAusAnker(anchor))));
  }


  function currentShadowStrength() {
    const b = _bahnStil();
    return b ? (+b.shadow || 0) : (parseFloat(document.getElementById("anim-shadow-strength")?.value) || 0);
  }
  function currentShadowDir() {   // v0.9.478 — globale Schatten-Richtung (Grad)
    var v = parseFloat(document.getElementById("anim-shadow-dir")?.value);
    return isFinite(v) ? v : 45;
  }
  // v0.9.309 — kein Toggle mehr: „an" = Stärke > 0.
  function currentShadowEnabled() {
    return currentShadowStrength() > 0;
  }
  function currentGlowEnabled() {
    return currentGlowStrength() > 0;
  }
  function currentGlowStrength() {
    const b = _bahnStil();
    return b ? (+b.glow || 0) : (parseFloat(document.getElementById("anim-glow-strength")?.value) || 0);
  }
  function currentAlphaEnabled() {
    // v0.6.0: Alpha-Modus = Stil "alpha". Vorher eigene Checkbox.
    return document.getElementById("anim-style")?.value === "alpha";
  }

  // v0.9.407 — „OSM-Stil aktiv?" — true wenn die Engine im OSM-Modus läuft (kein
  // Token) ODER (Mapbox-Engine, aber ein OSM-Raster-Stil ist gewählt — Tour-Map).
  // Nötig, weil Mapbox-GL-v3-only-Paint (`line-z-offset`, 3D-Terrain/DEM) auf einem
  // reinen Raster-Stil die Track-Layer (Glow/Linie/Highlight) NICHT rendert → Track
