    g.beginPath();
    g.moveTo(0, -13 * d); g.lineTo(9.5 * d, 11 * d);
    g.lineTo(0, 6 * d);   g.lineTo(-9.5 * d, 11 * d);
    g.closePath();
    g.fillStyle = "#ffffff";
    g.strokeStyle = farbe || "#ff6b35";
    g.lineWidth = 3 * d; g.lineJoin = "round";
    g.shadowColor = "rgba(0,0,0,0.35)"; g.shadowBlur = 6 * d;
    g.fill();
    g.shadowColor = "transparent";
