    // v0.9.180 — Panel hängt jetzt an document.body (nicht am Karten-Container),
    // damit man es über die Karte HINAUS ziehen kann (z.B. auf die Sidebar).
    // Position daher in SEITEN-Koordinaten (Container-Offset + map.project).
    function _animSignsPositionEditor(panel, lon, lat) {
      if (!map) return;
      try {
        const p = map.project([Number(lon), Number(lat)]);
        const r = map.getContainer().getBoundingClientRect();
        const vw = window.innerWidth, vh = window.innerHeight;
        const pw = panel.offsetWidth || 286, ph = panel.offsetHeight || 300;
        let x = r.left + p.x + 18, y = r.top + p.y - ph / 2;
        if (x + pw > vw - 8) x = r.left + p.x - pw - 18;   // kein Platz rechts → links vom Schild
        x = Math.max(8, Math.min(vw - pw - 8, x));
        y = Math.max(8, Math.min(vh - ph - 8, y));
        panel.style.left = x + "px"; panel.style.top = y + "px";
      } catch (_) { panel.style.left = "60px"; panel.style.top = "60px"; }
    }
    // v0.9.523 — installierte System-Schriften ins Schilder-Dropdown (Nutzer-Idee
  // aus Spanien). Die Liste kommt EINMAL vom Backend (Browser darf Schriften
  // nicht aufzählen), danach aus dem Modul-Cache. Ein Fehlschlag ist still —
  // dann bleiben eben die sechs eingebauten Familien.
  let _sysFonts = null;
  async function _seFuelleSystemFonts(sel) {
    if (!sel) return;
    try {
      if (_sysFonts === null) {
        const r = await api().system_fonts();
        _sysFonts = (r && r.ok && Array.isArray(r.fonts)) ? r.fonts : [];
      }
      if (!_sysFonts.length || sel.querySelector("optgroup")) return;
      const g = document.createElement("optgroup");
      g.label = t("signs.font.installed", "Installierte Schriften");
      const aktuell = sel.value;
      for (const f of _sysFonts) {
        const o = document.createElement("option");
        o.value = "sys:" + f;
        o.textContent = f;
        // 27.08.2026 (Beta-Tester, „Idea 1") — Den Namen einer Schrift IN der
        // Schrift zeigen, wie es der Schriftdialog von Windows macht. Kostet
        // nichts: Die Schrift ist ja installiert, ein `font-family` am
        // <option> genügt. Zwei Vorbehalte, die die Sache klein halten:
        // Symbolschriften (Wingdings & Co.) werden dadurch unlesbar, deshalb
        // steht der Name zusätzlich im Titel; und einige Browser ignorieren
        // die Auszeichnung an <option> — dann sieht es aus wie vorher.
        o.style.fontFamily = `"${f.replace(/"/g, "")}", sans-serif`;
        o.title = f;
        if (o.value === aktuell) o.selected = true;
        g.appendChild(o);
      }
      sel.appendChild(g);
      // Falls das Schild schon eine sys:-Schrift hat, die als Einzel-Option
      // oben klebt: durch die Gruppen-Option ersetzen (keine Dubletten).
      const dublette = [...sel.options].filter(o => o.value === aktuell && o.parentElement !== g);
      if (dublette.length && aktuell.indexOf("sys:") === 0) dublette.forEach(o => o.remove());
    } catch (_) {}
  }

    // v0.9.178 — Editor-Panel an der Kopfzeile frei verschiebbar machen.
    function _animSignsMakeDraggable(panel) {
      const head = panel.querySelector(".sign-editor-head");
      if (!head) return;
      head.style.cursor = "move";
      head.style.touchAction = "none";
      head.style.userSelect = "none";
      let dragging = false, sx = 0, sy = 0, ox = 0, oy = 0;
      const onMove = (e) => {
        if (!dragging) return;
        // v0.9.180 — frei im ganzen Fenster (Panel hängt an body), auch über die Karte hinaus
        const pw = panel.offsetWidth, ph = panel.offsetHeight;
        let x = ox + (e.clientX - sx);
        let y = oy + (e.clientY - sy);
        x = Math.max(2, Math.min(window.innerWidth - pw - 2, x));
        y = Math.max(2, Math.min(window.innerHeight - ph - 2, y));
        panel.style.left = x + "px";
        panel.style.top = y + "px";
        e.preventDefault();
      };
      const onUp = (e) => {
        dragging = false;
        try { head.releasePointerCapture(e.pointerId); } catch (_) {}
        window.removeEventListener("pointermove", onMove);
        window.removeEventListener("pointerup", onUp);
        // v0.9.523 — Wunschposition dauerhaft merken (localStorage reicht:
        // reine Fenster-Vorliebe, gehört weder ins Projekt noch in die Cloud).
        try {
          localStorage.setItem("rz_signs_editor_pos", JSON.stringify({
            x: parseFloat(panel.style.left) || 0,
            y: parseFloat(panel.style.top) || 0,
          }));
        } catch (_) {}
      };
      head.addEventListener("pointerdown", (e) => {
        // Klick auf den Schließen-Button NICHT als Drag werten
        if (e.target.closest("#se-close")) return;
        dragging = true;
        panel._userMoved = true;   // ab jetzt nicht mehr automatisch ans Schild kleben
        sx = e.clientX; sy = e.clientY;
        ox = parseFloat(panel.style.left) || 0;
        oy = parseFloat(panel.style.top) || 0;
        try { head.setPointerCapture(e.pointerId); } catch (_) {}
        window.addEventListener("pointermove", onMove);
        window.addEventListener("pointerup", onUp);
        e.preventDefault();
      });
    }
