    for (const c of cs) { if (c[1] < la0) la0 = c[1]; if (c[1] > la1) la1 = c[1]; if (c[0] < lo0) lo0 = c[0]; if (c[0] > lo1) lo1 = c[0]; }
    const cl = Math.cos(((la0 + la1) / 2) * Math.PI / 180);
