    try {
      setTimeout(() => {
        const ph = window.__rzAnimPhotos;
        if (ph && ph.applyToMap) ph.applyToMap();
        const sg = window.__rzAnimSigns;   // v0.9.171 — Schilder für neue Track-Geometrie re-attachen
        if (sg && sg.attach) { sg.attach(); sg.renderList(); }
      }, 50);
    } catch (_) {}
