      for (const typ of ["click", "mousedown", "dblclick", "wheel"]) el.addEventListener(typ, (ev) => ev.stopPropagation());
      map.getContainer().appendChild(el);
      _etMenue = el;
      _etMenueHook = () => _etMenueLage();
      map.on("move", _etMenueHook);
